# Step 1: Clean and isolate list strings
unique_names = list(dict.fromkeys([name.strip() for name in data.split() if name.strip()]))
db_names = list(set([name.strip() for name in db_data.split() if name.strip()]))

# Step 2: Establish the fuzzy threshold (0.85 means 85% match required to be considered 'found')
THRESHOLD = 0.85
missing_cattle = []

for name in unique_names:
    has_match = False
    for db_name in db_names:
        # Calculate similarity match ratio between the two names
        similarity = difflib.SequenceMatcher(None, name, db_name).ratio()
        if similarity >= THRESHOLD:
            has_match = True
            break # Break loop early since it matches a DB record fuzzy-wise
            
    if not has_match:
        missing_cattle.append(name)

# Step 3: Output results to file
os.makedirs("generated", exist_ok=True)
with open("generated/hello.txt", "w", encoding="utf-8") as file:
    file.write("\n".join(missing_cattle))

print(f"Total Unique incoming names: {len(unique_names)}")
print(f"Filtered out via fuzzy logic: {len(unique_names) - len(missing_cattle)}")
print(f"Written to 'generated/hello.txt': {len(missing_cattle)} genuinely missing names.")
